interface TableDragSortOptions<TData extends RowData> {
  rowKey: Extract<keyof TData, string | number>;
  onDragSortEnd?: (newData: TData[]) => void;
}

export type TableRowKey<TData extends RowData> =
  | Extract<keyof TData, string | number>
  | ((record: TData) => string | number);

export interface DataTableRenderContext<TData extends RowData> {
  table: TableInstance<TData>;
  rows: Row<TData>[];
  selectedRows: Row<TData>[];
  tableSize: DataTableDensityValue;
  onTableSizeChange: (size: DataTableDensityValue) => void;
  loading: boolean;
  refresh?: () => void;
  labels: TableLabels;
  defaultColumnOrder: string[];
  defaultColumnPinning: ColumnPinningState;
  size?: ButtonSize;
}

type DataTableSlot<TData extends RowData> =
  | ReactNode
  | ((context: DataTableRenderContext<TData>) => ReactNode);

function getLeafColumnDefs<TData extends RowData, TValue>(
  columns: ColumnDef<TData, TValue>[],
): ColumnDef<TData, TValue>[] {
  return columns.flatMap((column) =>
    "columns" in column && Array.isArray(column.columns)
      ? getLeafColumnDefs(column.columns)
      : [column],
  );
}

function useTableController<TData extends RowData, TValue>({
  columns,
  data,
  setData,
  rowKey,
  paginationOptions,
  dragSort,
  tableOptions,
  manual = false,
  requestTotal,
  unknownTotal = false,
  pagination,
  setPagination,
  sorting,
  setSorting,
  columnFilters,
  setColumnFilters,
}: {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  setData: Dispatch<SetStateAction<TData[]>>;
  rowKey?: TableRowKey<TData>;
  pagination: PaginationState;
  setPagination: Dispatch<SetStateAction<PaginationState>>;
  sorting: SortingState;
  setSorting: Dispatch<SetStateAction<SortingState>>;
  columnFilters: ColumnFiltersState;
  setColumnFilters: Dispatch<SetStateAction<ColumnFiltersState>>;
  paginationOptions?: false;
  dragSort?: false | TableDragSortOptions<TData>;
  tableOptions?: TableFeatureOptions;
  manual?: boolean;
  requestTotal?: number;
  unknownTotal?: boolean;
}) {
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({});
  const [tableSize, setTableSize] = useState<DataTableDensityValue>("default");
  const tableRef = useRef<HTMLTableElement>(null);
  const tableColumns = useMemo(
    () => withTableColumnDefaults(columns),
    [columns],
  );
  const resolvedColumnVisibility = useMemo<VisibilityState>(
    () => ({
      ...columnVisibility,
      ...Object.fromEntries(
        getLeafColumnDefs(tableColumns)
          .filter((column) => column.meta?.filterOnly)
          .map((column, index) => [getColumnDefId(column, index), false]),
      ),
    }),
    [columnVisibility, tableColumns],
  );
  const rankedSortedRowModel = useMemo(() => {
    const sortedRowModel = createSortedRowModel<TableFeatures, TData>();

    return (table: TableInstance<TData>) => {
      const getSorted = sortedRowModel(table);

      return () => {
        const rowModel = getSorted();
        if (table.options.manualSorting || table.store.state.sorting.length > 0)
          return rowModel;

        const rankedColumnId = rowModel.rows
          .flatMap((row) =>
            Object.keys(row.columnFiltersMeta).filter(
              (columnId) => !!row.columnFiltersMeta[columnId]?.itemRank,
            ),
          )
          .at(0);
        if (!rankedColumnId) return rowModel;

        return {
          ...rowModel,
          rows: sortRowsByRank(rowModel.rows, rankedColumnId),
          flatRows: sortRowsByRank(rowModel.flatRows, rankedColumnId),
        };
      };
    };
  }, []);
  const columnState = useTableColumnState(tableColumns, tableOptions);
  const resetToFirstPage = useCallback(() => {
    setPagination((current) => ({ ...current, pageIndex: 0 }));
  }, [setPagination]);
  const handleSortingChange = useCallback<OnChangeFn<SortingState>>(
    (updater) => {
      setSorting(updater);
      resetToFirstPage();
    },
    [resetToFirstPage, setSorting],
  );
  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updater) => {
      setColumnFilters(updater);
      resetToFirstPage();
    },
    [resetToFirstPage, setColumnFilters],
  );
  const reactTableOptions: TableOptions<TData> = {
    features: {
      ...uiTableFeatures,
      sortedRowModel:
        rankedSortedRowModel as typeof uiTableFeatures.sortedRowModel,
    },
    data,
    // Table v9 erases individual accessor value types at the table boundary.
    columns: tableColumns as ColumnDef<TData>[],
    state: {
      sorting,
      columnVisibility: resolvedColumnVisibility,
      rowSelection,
      columnFilters,
      columnOrder: columnState.columnOrder,
      columnPinning: columnState.columnPinning,
      pagination,
    },
    autoResetPageIndex: false,
    enableRowSelection: true,
    enableColumnPinning: columnState.pinningEnabled,
    onRowSelectionChange: setRowSelection,
    onSortingChange: handleSortingChange,
    onColumnFiltersChange: handleColumnFiltersChange,
    onColumnVisibilityChange: setColumnVisibility,
    onColumnOrderChange: columnState.setColumnOrder,
    onColumnPinningChange: columnState.handleColumnPinningChange,
    onPaginationChange: setPagination,
  };
  if (manual) {
    reactTableOptions.manualPagination = true;
    reactTableOptions.manualSorting = tableOptions?.manual !== true;
    reactTableOptions.manualFiltering = true;
    reactTableOptions.rowCount = requestTotal;
    if (unknownTotal) reactTableOptions.pageCount = -1;
  }
  if (paginationOptions === false || dragSort)
    reactTableOptions.manualPagination = true;
  if (dragSort) {
    reactTableOptions.manualSorting = true;
    reactTableOptions.enableSorting = false;
  }
  const resolvedRowKey = rowKey ?? (dragSort ? dragSort.rowKey : undefined);
  if (resolvedRowKey !== undefined) {
    reactTableOptions.getRowId = (row) =>
      String(
        typeof resolvedRowKey === "function"
          ? resolvedRowKey(row)
          : row[resolvedRowKey],
      );
  }
  const table = useTable(reactTableOptions);
  const pageCount = table.getPageCount();

  useEffect(() => {
    if (
      paginationOptions === false ||
      pageCount <= 0 ||
      pagination.pageIndex < pageCount
    )
      return;
    setPagination((current) => ({ ...current, pageIndex: pageCount - 1 }));
  }, [pageCount, pagination.pageIndex, paginationOptions, setPagination]);

  const dragSortEnabled = !!dragSort;
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );
  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event;
      if (!over || active.id === over.id) return;

      const rows = table.getRowModel().rows;
      const oldIndex = rows.findIndex((row) => row.id === String(active.id));
      const newIndex = rows.findIndex((row) => row.id === String(over.id));
      if (oldIndex === -1 || newIndex === -1) return;

      const oldDataIndex = data.indexOf(rows[oldIndex].original);
      const newDataIndex = data.indexOf(rows[newIndex].original);
      if (oldDataIndex === -1 || newDataIndex === -1) return;

      const nextData = arrayMove(data, oldDataIndex, newDataIndex);
      if (nextData === data) return;

      setData(nextData);
      if (dragSort) dragSort.onDragSortEnd?.(nextData);
    },
    [data, dragSort, setData, table],
  );
  const pinnedOffsets = useTablePinnedColumnOffsets(
    table,
    tableRef,
    dragSortEnabled,
  );
  const rows = table.getRowModel().rows;
  const selectedRows = table.getFilteredSelectedRowModel().rows;
  const visibleColumns = table.getVisibleLeafColumns();
  const visibleColumnCount = visibleColumns.length + (dragSortEnabled ? 1 : 0);

  return {
    table,
    tableRef,
    tableSize,
    setTableSize,
    rows,
    selectedRows,
    visibleColumns,
    visibleColumnCount,
    pinnedOffsets,
    sensors,
    handleDragEnd,
    dragSortEnabled,
    defaultColumnOrder: columnState.defaultColumnOrder,
    defaultColumnPinning: columnState.defaultColumnPinning,
  };
}

function renderTableSlot<TData extends RowData>(
  slot: DataTableSlot<TData> | undefined,
  context: DataTableRenderContext<TData>,
) {
  if (slot === false) return undefined;
  if (typeof slot === "function") return slot(context);
  return slot;
}

function getTablePaddingClass(size: DataTableDensityValue) {
  if (size === "compact") return "py-1";
  if (size === "middle") return "py-2";
  return "py-3";
}

function getAriaSort(canSort: boolean, sorted: false | "asc" | "desc") {
  if (!canSort) return undefined;
  if (sorted === "asc") return "ascending";
  if (sorted === "desc") return "descending";
  return "none";
}

export interface DataTableProps<TData extends RowData, TValue = unknown> {
  readonly columns: ColumnDef<TData, TValue>[];
  readonly data?: TData[];
  readonly rowKey?: TableRowKey<TData>;
  readonly request?: (
    params: DataTableState,
  ) =>
    | Promise<{ readonly data: TData[]; readonly total?: number }>
    | { readonly data: TData[]; readonly total?: number };
  readonly initialState?: Partial<DataTableState>;
  readonly onChange?: (state: DataTableState) => void;
  readonly children?: (
    context: DataTableRenderContext<TData> & { content: ReactNode },
  ) => ReactNode;
  readonly size?: ButtonSize;
  readonly bulkToolbar?: false | DataTableSlot<TData>;
  readonly pagination?: false;
  readonly dragSort?: false | TableDragSortOptions<TData>;
  readonly loading?: boolean | { readonly rows?: number };
  readonly layout?: "full" | "auto";
  readonly table?: TableFeatureOptions;
  readonly className?: string;
  readonly label?: string;
  readonly labels?: TableLabelOverrides;
}

/** Feature-rich local or remote TanStack data table. */
export function DataTable<TData extends RowData, TValue>({
  columns,
  data,
  rowKey,
  request,
  initialState,
  onChange,
  children,
  size,
  bulkToolbar,
  pagination,
  dragSort,
  loading,
  layout,
  table,
  className,
  label = "Data table",
  labels: labelOverrides,
}: Readonly<DataTableProps<TData, TValue>>) {
  const labels = resolveTableLabels(labelOverrides);
  const dragContextId = useId();
  const [tableData, setTableData] = useState<TData[]>(data ?? []);
  const [requestLoading, setRequestLoading] = useState(false);
  const [requestError, setRequestError] = useState<unknown>();
  const [requestTotal, setRequestTotal] = useState<number>();
  const [requestVersion, setRequestVersion] = useState(0);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>(
    initialState?.columnFilters ?? [],
  );
  const [sorting, setSorting] = useState<SortingState>(
    initialState?.sorting ?? [],
  );
  const [paginationState, setPagination] = useState<PaginationState>(
    initialState?.pagination ?? {
      pageIndex: 0,
      pageSize: 10,
    },
  );

  const initialStateKey = JSON.stringify(initialState);
  const previousInitialStateKey = useRef(initialStateKey);
  const syncingInitialState = useRef(false);
  useEffect(() => {
    if (previousInitialStateKey.current === initialStateKey) return;
    previousInitialStateKey.current = initialStateKey;
    syncingInitialState.current = true;
    const nextPagination = initialState?.pagination;
    const nextSorting = initialState?.sorting;
    const nextColumnFilters = initialState?.columnFilters;

    if (nextPagination) {
      setPagination((current) =>
        current.pageIndex === nextPagination.pageIndex &&
        current.pageSize === nextPagination.pageSize
          ? current
          : nextPagination,
      );
    }
    if (nextSorting) {
      setSorting((current) =>
        JSON.stringify(current) === JSON.stringify(nextSorting)
          ? current
          : nextSorting,
      );
    }
    if (nextColumnFilters) {
      setColumnFilters((current) =>
        JSON.stringify(current) === JSON.stringify(nextColumnFilters)
          ? current
          : nextColumnFilters,
      );
    }
  }, [
    initialStateKey,
    initialState?.columnFilters,
    initialState?.pagination,
    initialState?.sorting,
  ]);
  const state = useMemo<DataTableState>(
    () => ({ pagination: paginationState, sorting, columnFilters }),
    [paginationState, sorting, columnFilters],
  );
  const previousState = useRef(state);

  useEffect(() => {
    if (request) return;
    setTableData(data ?? []);
    setRequestLoading(false);
    setRequestError(undefined);
    setRequestTotal(undefined);
  }, [data, request]);

  useEffect(() => {
    if (syncingInitialState.current) {
      const matches =
        (!initialState?.pagination ||
          JSON.stringify(state.pagination) ===
            JSON.stringify(initialState.pagination)) &&
        (!initialState?.sorting ||
          JSON.stringify(state.sorting) ===
            JSON.stringify(initialState.sorting)) &&
        (!initialState?.columnFilters ||
          JSON.stringify(state.columnFilters) ===
            JSON.stringify(initialState.columnFilters));
      if (matches) syncingInitialState.current = false;
      previousState.current = state;
      return;
    }
    if (previousState.current === state) return;
    previousState.current = state;
    onChange?.(state);
  }, [onChange, state, initialState]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: requestVersion explicitly invalidates the stable request for refresh and retry.
  useEffect(() => {
    if (!request) return;

    let canceled = false;
    setRequestLoading(true);
    setRequestError(undefined);

    Promise.resolve()
      .then(() => request(state))
      .then((result) => {
        if (canceled) return;
        setTableData(result.data);
        setRequestTotal(result.total);
      })
      .catch((error) => {
        if (canceled) return;
        setRequestError(error);
        setTableData([]);
        setRequestTotal(undefined);
      })
      .finally(() => {
        if (!canceled) setRequestLoading(false);
      });

    return () => {
      canceled = true;
    };
  }, [request, state, requestVersion]);

  const refresh = request
    ? () => setRequestVersion((version) => version + 1)
    : undefined;
  const loadingRows = typeof loading === "object" ? (loading.rows ?? 5) : 5;
  const tableLoading =
    (loading !== undefined && loading !== false) || requestLoading;
  const loadingEnabled = tableLoading && tableData.length === 0;
  const overlayLoading = tableLoading && tableData.length > 0;
  const tableController = useTableController({
    columns,
    data: tableData,
    setData: setTableData,
    rowKey,
    paginationOptions: pagination,
    dragSort,
    tableOptions: table,
    manual: !!request || table?.manual === true,
    requestTotal,
    unknownTotal: !!request && requestTotal === undefined,
    pagination: paginationState,
    setPagination,
    sorting,
    setSorting,
    columnFilters,
    setColumnFilters,
  });
  const renderContext: DataTableRenderContext<TData> = {
    table: tableController.table,
    rows: tableController.rows,
    selectedRows: tableController.selectedRows,
    tableSize: tableController.tableSize,
    onTableSizeChange: tableController.setTableSize,
    loading: tableLoading,
    refresh,
    labels,
    defaultColumnOrder: tableController.defaultColumnOrder,
    defaultColumnPinning: tableController.defaultColumnPinning,
    size,
  };
  const isFullLayout = (layout ?? "auto") === "full";
  const bulkActions = renderTableSlot(bulkToolbar, renderContext);
  const stickyHeader = table?.stickyHeader ?? true;
  const paddingClass = getTablePaddingClass(tableController.tableSize);
  const visibleDataColumnCount = tableController.visibleColumns.filter(
    (column) => getSystemColumnPinning(column.id) === undefined,
  ).length;
  const fixedColumnsWidth = tableController.visibleColumns.reduce(
    (total, column) => total + (column.columnDef.meta?.__uiTableFixedSize ?? 0),
    tableController.dragSortEnabled
      ? tableController.pinnedOffsets.dragWidth
      : 0,
  );
  const hasFlexibleColumns = tableController.visibleColumns.some(
    (column) => column.columnDef.meta?.__uiTableFixedSize === undefined,
  );
  const tableStyle: CSSProperties = {
    width: hasFlexibleColumns ? "100%" : fixedColumnsWidth,
  };
  const content = (
    <>
      <div
        data-slot="data-table-viewport"
        className={cn("relative min-w-0", isFullLayout && "min-h-0 flex-1")}
      >
        <div
          data-slot="ui-table-scroll-area"
          inert={overlayLoading}
          className={cn(
            "w-full max-w-full overflow-auto rounded-2xl border *:data-[slot=table-container]:overflow-visible",
            isFullLayout && "h-full min-h-0",
          )}
        >
          <TablePrimitive
            aria-label={label}
            aria-busy={tableLoading}
            ref={tableController.tableRef}
            className="table-auto border-separate border-spacing-0"
            style={tableStyle}
          >
            <colgroup>
              {tableController.dragSortEnabled && (
                <col
                  style={{ width: tableController.pinnedOffsets.dragWidth }}
                />
              )}
              {tableController.visibleColumns.map((column) => (
                <col
                  key={column.id}
                  style={{ width: column.columnDef.meta?.__uiTableFixedSize }}
                />
              ))}
            </colgroup>
            <TableHeader data-slot="ui-table-header">
              {tableController.table
                .getHeaderGroups()
                .map((headerGroup, headerIndex) => (
                  <TableRow key={headerGroup.id} className="bg-background">
                    {tableController.dragSortEnabled && (
                      <TableHead
                        data-ui-table-drag-column=""
                        scope="col"
                        style={{
                          top: stickyHeader
                            ? tableController.pinnedOffsets.headerTop[
                                headerIndex
                              ]
                            : undefined,
                        }}
                        className={cn(
                          "border-b",
                          "sticky inset-s-0 z-20 w-10 bg-background px-2 text-center",
                          stickyHeader && "top-0 z-30",
                        )}
                      >
                        <span className="sr-only">{labels.reorderRows}</span>
                      </TableHead>
                    )}
                    {headerGroup.headers.map((header) => {
                      const canSort =
                        !tableController.dragSortEnabled &&
                        header.column.getCanSort();
                      const sorted = header.column.getIsSorted();
                      const pinned = header.column.getIsPinned();
                      const align =
                        header.column.columnDef.meta?.align ??
                        (pinned === "end" ? "end" : pinned || undefined);
                      return (
                        <TableHead
                          key={header.id}
                          scope={
                            header.subHeaders.length > 0 ? "colgroup" : "col"
                          }
                          colSpan={header.colSpan}
                          className={cn(
                            "border-b",
                            stickyHeader && "sticky top-0 z-10 bg-inherit",
                            pinned && "bg-background",
                            getPinnedColumnClassName(
                              header.column,
                              header.column.getIsPinned() && stickyHeader
                                ? "z-30"
                                : undefined,
                            ),
                            align === "center" &&
                              "text-center [&>div]:justify-center",
                            align === "end" && "text-end [&>div]:justify-end",
                            align === "start" &&
                              "text-start [&>div]:justify-start",
                            header.column.columnDef.meta?.className,
                          )}
                          style={{
                            ...getPinnedColumnStyle(
                              header.column,
                              tableController.pinnedOffsets,
                            ),
                            top: stickyHeader
                              ? tableController.pinnedOffsets.headerTop[
                                  headerIndex
                                ]
                              : undefined,
                          }}
                          data-ui-table-column-id={header.column.id}
                          aria-sort={getAriaSort(canSort, sorted)}
                        >
                          {!header.isPlaceholder && (
                            <DataTableColumnHeader
                              column={header.column}
                              title={flexRender(
                                header.column.columnDef.header,
                                header.getContext(),
                              )}
                              sortable={canSort}
                              align={align ?? "start"}
                              disableHiding={
                                getSystemColumnPinning(header.column.id) ===
                                  undefined && visibleDataColumnCount <= 1
                              }
                              labels={labels}
                            />
                          )}
                        </TableHead>
                      );
                    })}
                  </TableRow>
                ))}
            </TableHeader>
            <TableBodyPrimitive className="[&_tr:last-child>td]:border-b-0">
              <TableBody
                rows={tableController.rows}
                visibleColumns={tableController.visibleColumns}
                visibleColumnCount={tableController.visibleColumnCount}
                dragSort={tableController.dragSortEnabled}
                loading={loadingEnabled}
                loadingRows={loadingRows}
                paddingClass={paddingClass}
                emptyFallbackText={requestError ? labels.loadFailed : undefined}
                onRetry={requestError ? refresh : undefined}
                labels={labels}
                pinnedOffsets={tableController.pinnedOffsets}
              />
            </TableBodyPrimitive>
          </TablePrimitive>
        </div>
        {overlayLoading && (
          <div
            data-slot="data-table-loading"
            role="status"
            aria-live="polite"
            className="absolute inset-0 z-40 grid place-items-center rounded-2xl bg-background/60"
          >
            <div className="flex items-center gap-2 rounded-3xl border bg-popover px-4 py-2 text-popover-foreground text-sm shadow-sm">
              <Loader label={labels.loading} />
              {labels.loading}
            </div>
          </div>
        )}
      </div>
      {pagination !== false && !dragSort && (
        <div className={isFullLayout ? "shrink-0" : undefined}>
          <DataTablePagination
            table={tableController.table}
            hasNextPage={
              requestTotal === undefined && request
                ? tableData.length >= paginationState.pageSize
                : undefined
            }
            labels={labels}
            disabled={tableLoading}
          />
        </div>
      )}
    </>
  );
  const tableContent = (
    <>
      {tableController.dragSortEnabled && !loadingEnabled ? (
        <DndContext
          id={dragContextId}
          sensors={tableController.sensors}
          collisionDetection={closestCenter}
          onDragEnd={tableController.handleDragEnd}
        >
          {content}
        </DndContext>
      ) : (
        content
      )}
      {bulkActions != null && (
        <TableBulkActions
          table={tableController.table}
          labels={labels}
          disabled={tableLoading}
        >
          <div className="flex shrink-0 items-center justify-end gap-2">
            {bulkActions}
          </div>
        </TableBulkActions>
      )}
    </>
  );
  return (
    <div
      data-slot="data-table"
      className={cn(
        "min-w-0 max-w-full",
        "flex flex-col gap-3",
        isFullLayout && "h-full min-h-0",
        className,
      )}
    >
      {children
        ? children({ ...renderContext, content: tableContent })
        : tableContent}
    </div>
  );
}

export type { TableLabelOverrides, TableLabels } from "@/components/blocks/data-table/labels";
export type { ColumnDef as DataTableColumnDef, TableFeatures } from "@/components/blocks/data-table/types";

import type { RowData } from "@tanstack/react-table";
import {
  Pagination,
  PaginationControls,
  PaginationInfo,
  PaginationPageSize,
} from "@/components/ui/pagination";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import type { Table } from "@/components/blocks/data-table/types";

export function DataTablePagination<TData extends RowData>({
  table,
  labels = defaultTableLabels,
  disabled = false,
  hasNextPage,
}: {
  table: Table<TData>;
  labels?: TableLabels;
  disabled?: boolean;
  hasNextPage?: boolean;
}) {
  return (
    <Pagination
      disabled={disabled}
      page={table.store.state.pagination.pageIndex + 1}
      onPageChange={(page) => table.setPageIndex(page - 1)}
      perPage={table.store.state.pagination.pageSize}
      totalCount={table.getPageCount() >= 0 ? table.getRowCount() : undefined}
      hasNextPage={hasNextPage ?? table.getCanNextPage()}
      labels={{
        firstPage: labels.paginationFirstPage,
        previousPage: labels.paginationPreviousPage,
        nextPage: labels.paginationNextPage,
        lastPage: labels.paginationLastPage,
        pageNumber: labels.paginationPage(
          table.store.state.pagination.pageIndex + 1,
        ),
        pageSize: labels.paginationRows,
      }}
      className="px-1"
    >
      <PaginationInfo className="min-w-0 flex-1">
        {table.getPageCount() < 0
          ? labels.paginationLoadedRows(table.getRowModel().rows.length)
          : labels.paginationTotalRows(table.getRowCount())}
      </PaginationInfo>
      <PaginationPageSize
        value={table.store.state.pagination.pageSize}
        onValueChange={(pageSize) => {
          table.setPageSize(pageSize);
          table.setPageIndex(0);
        }}
        options={[10, 20, 50, 100]}
        label={labels.paginationRows}
      />
      <PaginationControls
        controls={table.getPageCount() >= 0 ? "full" : "simple"}
      />
    </Pagination>
  );
}

"use client";

import { Loader } from "@/components/ui/loader";
import { RefreshCw } from "lucide-react";
import type { ComponentProps } from "react";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import { TooltipButton } from "@/components/blocks/data-table/tooltip-button";

export type DataTableRefreshProps = Omit<
  ComponentProps<typeof TooltipButton>,
  "children" | "tooltip" | "onClick"
> & {
  onRefresh: () => void;
  loading?: boolean;
  labels?: TableLabels;
};

/** Refresh action usable in any header, with the caller's request lifecycle. */
export function DataTableRefresh({
  onRefresh,
  loading = false,
  disabled = false,
  size = "icon-sm",
  variant = "ghost",
  labels = defaultTableLabels,
  ...props
}: DataTableRefreshProps) {
  return (
    <TooltipButton
      {...props}
      size={size}
      variant={variant}
      tooltip={labels.refresh}
      aria-busy={loading}
      disabled={disabled || loading}
      onClick={onRefresh}
    >
      {loading ? <Loader label={labels.loading} /> : <RefreshCw />}
    </TooltipButton>
  );
}

"use client";

import type { RowData } from "@tanstack/react-table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "cn";
import { Search, X } from "lucide-react";
import { useEffect, useState } from "react";
import { TableFilterSelect } from "@/components/blocks/data-table/filter-controls";
import { defaultTableLabels, type TableLabels } from "@/components/blocks/data-table/labels";
import type { Column, ColumnFiltersState, Table } from "@/components/blocks/data-table/types";

export interface DataTableSearchProps<TData extends RowData> {
  table: Table<TData>;
  disabled?: boolean;
  labels?: TableLabels;
  layout?: "inline" | "stacked";
  className?: string;
}

/** Independently placed search and filter controls with explicit apply/reset. */
export function DataTableSearch<TData extends RowData>({
  table,
  disabled = false,
  labels = defaultTableLabels,
  layout = "stacked",
  className,
}: Readonly<DataTableSearchProps<TData>>) {
  const inline = layout === "inline";
  const inputClassName = inline ? "w-50 max-w-full" : "w-full md:w-50";
  const searchColumns = getTableSearchColumns(table);
  const appliedFilters = table.store.state.columnFilters;
  const [draftFilters, setDraftFilters] =
    useState<ColumnFiltersState>(appliedFilters);
  const filterColumns = table
    .getAllLeafColumns()
    .filter((column) => column.columnDef.meta?.filter !== undefined);

  useEffect(() => setDraftFilters(appliedFilters), [appliedFilters]);

  if (searchColumns.length === 0 && filterColumns.length === 0) return null;

  const setDraftFilterValue = (columnId: string, value: unknown) => {
    setDraftFilters((current) => {
      const next = current.filter((filter) => filter.id !== columnId);
      if (isEmptyFilterValue(value)) return next;
      return [...next, { id: columnId, value }];
    });
  };
  const applyFilters = () => table.setColumnFilters(draftFilters);
  const hasConditions = draftFilters.length > 0 || appliedFilters.length > 0;

  return (
    <search
      className={cn(
        "flex min-w-0 max-w-full shrink-0 gap-2",
        inline
          ? "flex-wrap items-center"
          : "w-full flex-col md:flex-row md:items-center md:justify-between",
        className,
      )}
      onKeyDown={(event) => {
        if (
          event.key !== "Enter" ||
          !(event.target instanceof HTMLInputElement) ||
          !event.target.hasAttribute("data-ui-table-search-input")
        ) {
          return;
        }
        event.preventDefault();
        applyFilters();
      }}
    >
      <div
        className={cn(
          "flex min-w-0 max-w-full flex-wrap items-center gap-2",
          !inline && "flex-1",
        )}
      >
        {searchColumns.map((column) => {
          const rawValue = draftFilters.find(
            (filter) => filter.id === column.id,
          )?.value;
          const value = typeof rawValue === "string" ? rawValue : "";
          const configuredSearch = column.columnDef.meta?.search;
          const placeholder = getSearchPlaceholder(
            column,
            typeof configuredSearch === "object"
              ? configuredSearch.placeholder
              : undefined,
            labels,
          );

          const searchOptions =
            typeof configuredSearch === "object" ? configuredSearch : undefined;
          const fieldDisabled = disabled || searchOptions?.disabled === true;
          if (searchOptions?.render) {
            return (
              <div key={column.id} className={inputClassName}>
                {searchOptions.render({
                  value,
                  onChange: (next) => setDraftFilterValue(column.id, next),
                  disabled: fieldDisabled,
                })}
              </div>
            );
          }
          return (
            <Input
              type={searchOptions?.type ?? "text"}
              key={`search-${column.id}`}
              data-ui-table-search-input=""
              aria-label={placeholder}
              placeholder={placeholder}
              value={value}
              onChange={(event) =>
                setDraftFilterValue(column.id, event.target.value)
              }
              disabled={fieldDisabled}
              className={inputClassName}
            />
          );
        })}
        {filterColumns.map((column) => {
          const filter = column.columnDef.meta?.filter;
          if (!filter) return null;
          const rawValue = draftFilters.find(
            (item) => item.id === column.id,
          )?.value;
          const values = Array.isArray(rawValue)
            ? rawValue.filter(
                (item): item is string => typeof item === "string",
              )
            : [];

          return (
            <TableFilterSelect
              labels={labels}
              key={`filter-${column.id}`}
              options={filter.options.map((option) => {
                const count = table.options.manualFiltering
                  ? undefined
                  : column.getFacetedUniqueValues().get(option.value);
                return {
                  ...option,
                  textValue: option.label,
                  label:
                    count === undefined ? (
                      option.label
                    ) : (
                      <span className="flex min-w-0 flex-1 items-center justify-between gap-3">
                        <span className="truncate">{option.label}</span>
                        <span className="shrink-0 font-mono text-muted-foreground text-xs">
                          {count}
                        </span>
                      </span>
                    ),
                };
              })}
              placeholder={filter.placeholder ?? column.id}
              multiple={filter.multiple}
              searchable
              allowClear
              disabled={disabled || filter.disabled}
              value={getFilterValue(rawValue, values)}
              onChange={(value) => setDraftFilterValue(column.id, value)}
              className={inline ? "w-45 max-w-full" : "w-full md:w-45"}
            />
          );
        })}
      </div>
      <div className="flex shrink-0 items-center justify-end gap-2">
        {hasConditions && (
          <Button
            type="button"
            variant="ghost"
            disabled={disabled}
            onClick={() => {
              setDraftFilters([]);
              table.resetColumnFilters();
            }}
          >
            <X data-icon="inline-start" />
            {labels.reset}
          </Button>
        )}
        <Button type="button" disabled={disabled} onClick={applyFilters}>
          <Search data-icon="inline-start" />
          {labels.search}
        </Button>
      </div>
    </search>
  );
}

function getTableSearchColumns<TData extends RowData>(table: Table<TData>) {
  return table
    .getAllLeafColumns()
    .filter(
      (column) =>
        column.columnDef.meta?.search !== undefined &&
        column.columnDef.meta.search !== false,
    );
}

function getSearchPlaceholder<TData extends RowData>(
  column: Column<TData, unknown>,
  configuredPlaceholder: string | undefined,
  labels: TableLabels,
) {
  return configuredPlaceholder ?? labels.searchPlaceholder(column.id);
}

function getFilterValue(rawValue: unknown, values: string[]) {
  if (typeof rawValue === "string") return rawValue;
  if (Array.isArray(rawValue) && values.length === rawValue.length)
    return values;
  return undefined;
}

function isEmptyFilterValue(value: unknown) {
  return (
    value === undefined ||
    value === null ||
    value === "" ||
    (Array.isArray(value) && value.length === 0)
  );
}

import { compareItems, rankItem } from "@tanstack/match-sorter-utils";
import type { RowData } from "@tanstack/react-table";
import { Badge } from "@/components/ui/badge";
import { cn } from "cn";
import {
  createElement,
  type RefObject,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type { TablePinnedColumnOffsets } from "@/components/blocks/data-table/body";
import { CONTROL_COLUMN_WIDTH, getSystemColumnPinning } from "@/components/blocks/data-table/columns";
import type {
  ColumnDef,
  ColumnPinningState,
  FilterFn,
  OnChangeFn,
  Row,
  SortFn,
  Table,
} from "@/components/blocks/data-table/types";

const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

export interface TableFeatureOptions {
  stickyHeader?: boolean;
  /** Data is already filtered and paginated by an external query. */
  manual?: boolean;
  pinning?:
    | false
    | {
        value?: ColumnPinningState;
        onChange?: (value: ColumnPinningState) => void;
      };
}

export interface ColumnFilterMeta<TData extends RowData> {
  options: Array<{
    label: string;
    value: string;
  }>;
  placeholder?: string;
  multiple?: boolean;
  disabled?: boolean;
  onFilter?: (value: string, record: TData) => boolean;
}

export function getColumnDefId<TData extends RowData, TValue>(
  column: ColumnDef<TData, TValue>,
  index: number,
) {
  if (column.id) return column.id;
  if ("accessorKey" in column && column.accessorKey !== undefined)
    return String(column.accessorKey).replaceAll(".", "_");
  if (typeof column.header === "string") return column.header;
  return String(index);
}

function getLeafColumnIds<TData extends RowData, TValue>(
  columns: ColumnDef<TData, TValue>[],
): string[] {
  return columns.flatMap((column, index) =>
    "columns" in column && Array.isArray(column.columns)
      ? getLeafColumnIds(column.columns)
      : getColumnDefId(column, index),
  );
}

function getPinnedColumnIds<TData extends RowData, TValue>(
  columns: ColumnDef<TData, TValue>[],
  side: "start" | "end",
): string[] {
  return columns.flatMap((column, index) => {
    if ("columns" in column && Array.isArray(column.columns)) {
      return getPinnedColumnIds(column.columns, side);
    }
    const id = getColumnDefId(column, index);
    const pinned = column.meta?.pinned ?? getSystemColumnPinning(id);
    return pinned === side ? [id] : [];
  });
}

const emptyColumnPinning: ColumnPinningState = { start: [], end: [] };

export function useTableColumnState<TData extends RowData, TValue>(
  columns: ColumnDef<TData, TValue>[],
  tableOptions: TableFeatureOptions | undefined,
) {
  const pinningEnabled = tableOptions?.pinning !== false;
  const defaultColumnOrder = useMemo(
    () => getLeafColumnIds(columns),
    [columns],
  );
  const defaultColumnPinning = useMemo(
    () =>
      pinningEnabled
        ? {
            start: getPinnedColumnIds(columns, "start"),
            end: getPinnedColumnIds(columns, "end"),
          }
        : { start: [], end: [] },
    [columns, pinningEnabled],
  );
  const defaultColumnPinningKey = `${defaultColumnPinning.start?.join("\0") ?? ""}\x01${defaultColumnPinning.end?.join("\0") ?? ""}`;
  const defaultColumnPinningRef = useRef(defaultColumnPinning);
  defaultColumnPinningRef.current = defaultColumnPinning;
  const controlledColumnPinning =
    typeof tableOptions?.pinning === "object"
      ? tableOptions.pinning.value
      : undefined;
  const [columnOrder, setColumnOrder] = useState<string[]>(defaultColumnOrder);
  const [internalColumnPinning, setInternalColumnPinning] =
    useState<ColumnPinningState>(defaultColumnPinning);
  let columnPinning = internalColumnPinning;
  if (!pinningEnabled) columnPinning = emptyColumnPinning;
  else if (controlledColumnPinning) columnPinning = controlledColumnPinning;

  useEffect(() => {
    setColumnOrder((current) => {
      const remainingIds = new Set(defaultColumnOrder);
      const next = [
        ...current.filter((id) => remainingIds.delete(id)),
        ...remainingIds,
      ];
      return next.length === current.length &&
        next.every((id, index) => id === current[index])
        ? current
        : next;
    });
  }, [defaultColumnOrder]);
  // biome-ignore lint/correctness/useExhaustiveDependencies: the key tracks changed defaults read through the latest ref.
  useEffect(() => {
    if (!pinningEnabled || controlledColumnPinning) return;
    setInternalColumnPinning(defaultColumnPinningRef.current);
  }, [controlledColumnPinning, defaultColumnPinningKey, pinningEnabled]);

  const handleColumnPinningChange = useCallback<OnChangeFn<ColumnPinningState>>(
    (updater) => {
      const next =
        typeof updater === "function" ? updater(columnPinning) : updater;
      if (typeof tableOptions?.pinning === "object")
        tableOptions.pinning.onChange?.(next);
      if (
        !(
          typeof tableOptions?.pinning === "object" &&
          tableOptions.pinning.value
        )
      ) {
        setInternalColumnPinning(next);
      }
    },
    [columnPinning, tableOptions?.pinning],
  );

  return {
    columnOrder,
    setColumnOrder,
    columnPinning,
    handleColumnPinningChange,
    defaultColumnOrder,
    defaultColumnPinning,
    pinningEnabled,
  };
}

export function withTableColumnDefaults<TData extends RowData, TValue>(
  columns: ColumnDef<TData, TValue>[],
): ColumnDef<TData, TValue>[] {
  return columns.map((column, index) => {
    const children =
      "columns" in column && Array.isArray(column.columns)
        ? withTableColumnDefaults(column.columns)
        : undefined;
    const filter = column.meta?.filter;
    const columnId = getColumnDefId(column, index);
    const search = column.meta?.search;
    const shouldRenderFilterLabels = filter && column.cell === undefined;
    const shouldApplyFilter = filter && column.filterFn === undefined;
    const shouldApplySearchFilter =
      search && !filter && column.filterFn === undefined;
    const shouldApplyFuzzySort = search && column.sortFn === undefined;
    const systemPinned = getSystemColumnPinning(columnId);
    const compactSystemColumn = columnId === "select" || columnId === "drag";
    const fixedSize =
      column.size ?? (compactSystemColumn ? CONTROL_COLUMN_WIDTH : undefined);

    if (
      !children &&
      !shouldApplyFilter &&
      !shouldRenderFilterLabels &&
      !shouldApplySearchFilter &&
      !shouldApplyFuzzySort &&
      !systemPinned &&
      !column.meta?.filterOnly &&
      fixedSize === undefined
    ) {
      return column;
    }

    let systemOptions: Partial<
      Pick<ColumnDef<TData, TValue>, "enableHiding" | "meta">
    > = {};
    if (systemPinned) {
      systemOptions = {
        enableHiding: column.enableHiding ?? false,
        meta: {
          pinned: systemPinned,
          align: "center",
          ...column.meta,
          ...(fixedSize === undefined ? {} : { __uiTableFixedSize: fixedSize }),
          className: cn(
            compactSystemColumn && "w-10 px-2 [&:has([role=checkbox])]:pe-2",
            column.meta?.className,
          ),
        },
      };
    } else if (fixedSize !== undefined) {
      systemOptions = {
        meta: { ...column.meta, __uiTableFixedSize: fixedSize },
      };
    }

    return {
      ...column,
      ...(children ? { columns: children } : {}),
      ...(column.meta?.filterOnly ? { enableHiding: false } : {}),
      ...systemOptions,
      ...(shouldRenderFilterLabels
        ? {
            cell: ({ getValue }: { getValue: () => unknown }) => {
              const value = getValue();
              const values = Array.isArray(value) ? value : [value];
              return createElement(
                "div",
                { className: "flex flex-wrap gap-1" },
                values.map((item) => {
                  const text = String(item ?? "");
                  return createElement(
                    Badge,
                    { key: text, variant: "secondary" },
                    filter.options.find((option) => option.value === text)
                      ?.label ?? text,
                  );
                }),
              );
            },
          }
        : {}),
      ...(shouldApplyFilter
        ? {
            filterFn: getColumnFilterFn(filter),
          }
        : {}),
      ...(shouldApplySearchFilter
        ? {
            filterFn: ((row, columnId, filterValue, addMeta) => {
              const value = String(filterValue ?? "");
              if (!value) return true;

              const itemRank = rankItem(row.getValue(columnId), value);
              addMeta?.({ itemRank });
              return itemRank.passed;
            }) satisfies FilterFn<TData>,
          }
        : {}),
      ...(shouldApplyFuzzySort
        ? {
            sortFn: ((rowA, rowB, columnId) => {
              const rankA = rowA.columnFiltersMeta[columnId]?.itemRank;
              const rankB = rowB.columnFiltersMeta[columnId]?.itemRank;

              if (rankA && rankB) {
                const rankSort = compareItems(rankA, rankB);
                if (rankSort !== 0) return rankSort;
              }

              return collator.compare(
                String(rowA.getValue(columnId) ?? ""),
                String(rowB.getValue(columnId) ?? ""),
              );
            }) satisfies SortFn<TData>,
          }
        : {}),
    };
  });
}

function getColumnFilterFn<TData extends RowData>(
  filter: ColumnFilterMeta<TData>,
) {
  if (filter.onFilter) {
    return ((row, _columnId, filterValue) => {
      if (
        filterValue === undefined ||
        filterValue === null ||
        filterValue === ""
      )
        return true;
      if (Array.isArray(filterValue)) {
        if (filterValue.length === 0) return true;
        return filterValue.some((value) =>
          filter.onFilter?.(String(value), row.original),
        );
      }
      return !!filter.onFilter?.(String(filterValue), row.original);
    }) satisfies FilterFn<TData>;
  }

  if (filter.multiple) {
    return ((row, columnId, filterValue) => {
      if (
        filterValue === undefined ||
        filterValue === null ||
        filterValue === ""
      )
        return true;
      const rowValue = row.getValue(columnId);
      if (Array.isArray(filterValue)) {
        if (filterValue.length === 0) return true;
        return filterValue.includes(rowValue);
      }
      return filterValue === rowValue;
    }) satisfies FilterFn<TData>;
  }

  return "equals";
}

const collator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: "base",
});

export function sortRowsByRank<TData extends RowData>(
  rows: Row<TData>[],
  columnId: string,
) {
  return [...rows].sort((rowA, rowB) => {
    const rankA = rowA.columnFiltersMeta[columnId]?.itemRank;
    const rankB = rowB.columnFiltersMeta[columnId]?.itemRank;

    if (rankA && rankB) {
      const rankSort = compareItems(rankA, rankB);
      if (rankSort !== 0) return rankSort;
    }

    if (rankA) return -1;
    if (rankB) return 1;
    return rowA.index - rowB.index;
  });
}

export function useTablePinnedColumnOffsets<TData extends RowData>(
  table: Table<TData>,
  tableRef: RefObject<HTMLTableElement | null>,
  dragSort: boolean,
): TablePinnedColumnOffsets {
  const [offsets, setOffsets] = useState<TablePinnedColumnOffsets>(() =>
    getInitialPinnedColumnOffsets(table, dragSort),
  );
  const visibleColumnKey = table
    .getVisibleLeafColumns()
    .map((column) => column.id)
    .join("\0");
  const leftPinnedKey = (table.store.state.columnPinning.start ?? []).join(
    "\0",
  );
  const rightPinnedKey = (table.store.state.columnPinning.end ?? []).join("\0");
  const pinnedSizeKey = [
    ...table.getStartVisibleLeafColumns(),
    ...table.getEndVisibleLeafColumns(),
  ]
    .map(
      (column) =>
        `${column.id}:${column.columnDef.meta?.__uiTableFixedSize ?? "auto"}`,
    )
    .join("\0");

  useIsomorphicLayoutEffect(() => {
    const tableElement = tableRef.current;
    if (!tableElement) return;
    const measuredColumnIds = new Set(
      [
        ...table.getStartVisibleLeafColumns(),
        ...table.getEndVisibleLeafColumns(),
      ].map((column) => column.id),
    );

    const updateOffsets = () => {
      const widths = new Map<string, number>();

      for (const element of tableElement.querySelectorAll<HTMLElement>(
        "thead tr:last-child [data-ui-table-column-id]",
      )) {
        const columnId = element.dataset.uiTableColumnId;
        if (
          !columnId ||
          !measuredColumnIds.has(columnId) ||
          widths.has(columnId)
        )
          continue;
        widths.set(columnId, element.getBoundingClientRect().width);
      }

      const dragWidth = dragSort ? CONTROL_COLUMN_WIDTH : 0;
      const next: TablePinnedColumnOffsets = {
        start: {},
        end: {},
        dragWidth,
        headerTop: Array.from(
          tableElement.tHead?.rows ?? [],
          (row) => row.offsetTop,
        ),
      };
      let left = dragWidth;

      for (const column of table.getStartVisibleLeafColumns()) {
        next.start[column.id] = left;
        left +=
          widths.get(column.id) ??
          column.columnDef.meta?.__uiTableFixedSize ??
          column.getSize();
      }

      let right = 0;
      const rightColumns = table.getEndVisibleLeafColumns();
      for (let index = rightColumns.length - 1; index >= 0; index -= 1) {
        const column = rightColumns[index];
        next.end[column.id] = right;
        right +=
          widths.get(column.id) ??
          column.columnDef.meta?.__uiTableFixedSize ??
          column.getSize();
      }

      setOffsets((current) =>
        arePinnedColumnOffsetsEqual(current, next) ? current : next,
      );
    };

    updateOffsets();
    if (typeof ResizeObserver === "undefined") return undefined;

    let frame = 0;
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(updateOffsets);
    });
    for (const row of tableElement.tHead?.rows ?? []) observer.observe(row);
    for (const element of tableElement.querySelectorAll<HTMLElement>(
      "thead tr:last-child [data-ui-table-column-id]",
    )) {
      const columnId = element.dataset.uiTableColumnId;
      if (columnId && measuredColumnIds.has(columnId))
        observer.observe(element);
    }

    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [
    dragSort,
    leftPinnedKey,
    pinnedSizeKey,
    rightPinnedKey,
    table,
    tableRef,
    visibleColumnKey,
  ]);

  return offsets;
}

function getInitialPinnedColumnOffsets<TData extends RowData>(
  table: Table<TData>,
  dragSort: boolean,
) {
  const offsets: TablePinnedColumnOffsets = {
    start: {},
    end: {},
    dragWidth: dragSort ? CONTROL_COLUMN_WIDTH : 0,
    headerTop: table.getHeaderGroups().map((_, index) => index * 48),
  };
  let left = offsets.dragWidth;
  for (const column of table.getStartVisibleLeafColumns()) {
    offsets.start[column.id] = left;
    left += column.columnDef.meta?.__uiTableFixedSize ?? column.getSize();
  }

  let right = 0;
  const rightColumns = table.getEndVisibleLeafColumns();
  for (let index = rightColumns.length - 1; index >= 0; index -= 1) {
    const column = rightColumns[index];
    offsets.end[column.id] = right;
    right += column.columnDef.meta?.__uiTableFixedSize ?? column.getSize();
  }
  return offsets;
}

function arePinnedColumnOffsetsEqual(
  current: TablePinnedColumnOffsets,
  next: TablePinnedColumnOffsets,
) {
  for (const side of ["start", "end"] as const) {
    let currentCount = 0;
    let nextCount = 0;

    for (const [columnId, offset] of Object.entries(current[side])) {
      currentCount += 1;
      if (next[side][columnId] !== offset) return false;
    }

    for (const [columnId, offset] of Object.entries(next[side])) {
      nextCount += 1;
      if (current[side][columnId] !== offset) return false;
    }

    if (currentCount !== nextCount) return false;
  }

  return (
    current.dragWidth === next.dragWidth &&
    current.headerTop.length === next.headerTop.length &&
    current.headerTop.every((top, index) => top === next.headerTop[index])
  );
}

/** Props accepted by Table. */

[data-slot="ui-table-scroll-area"] {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;

  &:hover,
  &:focus-within {
    scrollbar-color: var(--muted-foreground) transparent;
  }
}

/* Standard scrollbar colors override WebKit styling and restore macOS overlay
   scrollbars, which can stay hidden on hover until the user actually scrolls. */
@supports selector(::-webkit-scrollbar) {
  [data-slot="ui-table-scroll-area"] {
    scrollbar-width: auto;
    scrollbar-color: auto;

    &::-webkit-scrollbar {
      width: 8px;
      height: 8px;
    }

    &::-webkit-scrollbar-track,
    &::-webkit-scrollbar-corner {
      background: transparent;
      box-shadow: none;
    }

    &::-webkit-scrollbar-thumb {
      border: 0;
      border-radius: 9999px;
      background: transparent;
    }

    &:hover,
    &:focus-within {
      scrollbar-color: auto;
    }

    &:hover::-webkit-scrollbar-thumb,
    &:focus-within::-webkit-scrollbar-thumb {
      background: color-mix(in oklab, var(--muted-foreground) 45%, transparent);
    }
  }
}

/* Sticky cells must paint the same opaque surface as their row. Transparent
   hover colors would blend twice and expose scrolling cells underneath them. */
[data-slot="data-table"] {
  & thead tr,
  & thead th {
    background-color: var(--background);
  }

  & tbody tr {
    --data-table-row-background: var(--background);
    background-color: var(--data-table-row-background);
  }

  & tbody tr:hover,
  & tbody tr:has([aria-expanded="true"]) {
    --data-table-row-background: color-mix(
      in oklab,
      var(--muted) 50%,
      var(--background)
    );
  }

  & tbody tr[data-state="selected"] {
    --data-table-row-background: var(--accent);
  }

  & tbody td {
    background-color: var(--data-table-row-background);
    transition: background-color 150ms ease;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="data-table"] tbody td {
    transition: none;
  }
}

import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import type { ComponentProps, ReactNode } from "react";

export type ButtonSize = NonNullable<ComponentProps<typeof Button>["size"]>;

export function TooltipButton({
  tooltip,
  ...props
}: ComponentProps<typeof Button> & { tooltip: ReactNode }) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            {...props}
            aria-label={
              props["aria-label"] ??
              (typeof tooltip === "string" ? tooltip : undefined)
            }
          />
        }
      />
      <TooltipContent>{tooltip}</TooltipContent>
    </Tooltip>
  );
}

