/** `glass` and `frosted` apply to the size select's trigger and menu. */
type PaginationPageSizeProps = Omit<React.ComponentProps<"div">, "onChange"> &
  GlassProps & {
    value: number;
    onValueChange: (value: number) => void;
    options?: readonly number[];
    label?: React.ReactNode;
    disabled?: boolean;
  };

function PaginationPageSize({
  value,
  onValueChange,
  options = [10, 20, 50, 100],
  label = "Rows per page",
  disabled = false,
  glass,
  frosted,
  className,
  ...props
}: PaginationPageSizeProps) {
  const context = usePagination();
  const id = React.useId();
  const size = safeInteger(value, context.perPage, 1);
  const sizes = [
    ...new Set([
      size,
      ...options.filter((option) => Number.isSafeInteger(option) && option > 0),
    ]),
  ].sort((a, b) => a - b);
  return (
    <div
      data-slot="pagination-page-size"
      className={cn("flex items-center gap-2", className)}
      {...props}
    >
      {label !== null && (
        <Label htmlFor={id} className="font-normal text-muted-foreground">
          {label}
        </Label>
      )}
      <Select
        value={size}
        disabled={disabled || context.disabled}
        onValueChange={(next) => {
          if (next !== null) onValueChange(next);
        }}
      >
        <SelectTrigger
          id={id}
          glass={glass}
          frosted={frosted}
          aria-label={context.labels.pageSize}
          className={cn(paginationControlClassName, "min-w-18")}
        >
          <SelectValue>{size}</SelectValue>
        </SelectTrigger>
        <SelectContent glass={glass} frosted={frosted}>
          {sizes.map((number) => (
            <SelectItem key={number} value={number}>
              {number}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

